from sympy import isprime

def find_solutions(max_p, max_m):
    solutions = []
    for p in range(3, max_p + 1):
        if not isprime(p):
            continue

        # a^(p-1) + b = p^m
        # b^(p-1) + a = p^n
        # a <= b

        # p^m = a^(p-1) + b
        # Since b >= a, p^m >= a^(p-1) + a
        # Also b = p^m - a^(p-1)
        # So (p^m - a^(p-1))^(p-1) + a = p^n

        for m in range(1, max_m + 1):
            pm = p**m
            # a^(p-1) < p^m
            # a < p^(m / (p-1))
            max_a = int(pm**(1/(p-1))) + 1
            for a in range(1, max_a + 1):
                b = pm - a**(p-1)
                if b >= a:
                    # Check if b^(p-1) + a is a power of p
                    val = b**(p-1) + a
                    if val > 0:
                        # Check if val is a power of p
                        temp_val = val
                        is_power = True
                        if temp_val == 0:
                            is_power = False
                        else:
                            while temp_val > 1:
                                if temp_val % p != 0:
                                    is_power = False
                                    break
                                temp_val //= p
                        if is_power:
                            solutions.append((p, a, b))
    return solutions

print(find_solutions(11, 10))

def check_p3(max_m):
    sols = []
    for m in range(1, max_m + 1):
        pm = 3**m
        for a in range(2, int(pm**0.5) + 1):
            b = pm - a**2
            if b >= a:
                val = b**2 + a
                # check if val is power of 3
                temp = val
                if temp > 0:
                    while temp % 3 == 0:
                        temp //= 3
                    if temp == 1:
                        sols.append((3, a, b))
    return sols

