    for p in range(3, max_p + 1):
        if not isprime(p):
            continue

        for m in range(1, max_m + 1):
            pm = p**m
            # a^(p-1) < pm
            # a < pm**(1/(p-1))
            max_a = int(pm**(1/(p-1))) + 1
            for a in range(2, max_a + 1):
                b = pm - a**(p-1)
                if b >= a:
                    val = b**(p-1) + a
                    if val > 0:
