from sympy import isprime

def check_condition(max_p, max_m):
    results = []
    for p in range(3, max_p + 1):
        if not isprime(p):
            continue
        for m in range(2, max_m + 1):
            pm = p**m
            # a < pm**(1/(p-1))
            max_a = int(pm**(1/(p-1))) + 1
            for a in range(2, max_a + 1):
                if (a**((p-1)**2) + a) % pm == 0:
                    results.append((p, m, a))
    return results

